// Art for the Stage 1 riddles: the stopped clock's face (a painting) and the
// atlas of scratched letters (drawn on a canvas once per run). Used by HallScene.

import * as THREE from 'three'
import type { Scratch } from '../../stage1/riddles'

/**
 * The painted clock face: AI-generated by the project owner (ChatGPT), no
 * hands, square, dial centred, plain numbers 1–12. See README credits.
 */
export const CLOCK_FACE_URL = '/stage1/clock-face.webp'

function hash(x: number, y: number): number {
  const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453
  return s - Math.floor(s)
}

/** One overlay cell: draws into a 128 × 128 px square whose left edge is at x0. */
export type CellPainter = (g: CanvasRenderingContext2D, x0: number, index: number) => void

export const OV_CELL = 128
export const OV_CELLS = 16

/**
 * The overlay atlas: sixteen 128 px cells side by side (the shader's uOvTex).
 * White on transparent for masks (scratches, dust, shade); coloured for ink
 * and tints.
 */
export function overlayAtlas(cells: CellPainter[]): THREE.Texture {
  const S = OV_CELL
  const c = document.createElement('canvas')
  c.width = S * OV_CELLS
  c.height = S
  const g = c.getContext('2d')!
  cells.slice(0, OV_CELLS).forEach((paint, i) => {
    g.save()
    g.beginPath(); g.rect(i * S, 0, S, S); g.clip()
    paint(g, i * S, i)
    g.restore()
  })
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.NoColorSpace
  t.generateMipmaps = true
  t.minFilter = THREE.LinearMipmapLinearFilter
  t.anisotropy = 8
  return t
}

/**
 * A scratched letter and, unless it is the red herring, its small number:
 * white strokes, cut with a blade in a few passes that don't quite line up.
 * The letter fills 62% of the cell's height.
 */
export function scratchCell(sc: Pick<Scratch, 'letter' | 'number'>): CellPainter {
  return (g, x0, i) => {
    g.strokeStyle = '#fff'
    g.lineCap = 'round'
    g.lineJoin = 'round'
    g.textAlign = 'center'
    g.textBaseline = 'alphabetic'
    g.font = 'bold 96px Georgia, "Times New Roman", serif'
    for (let p = 0; p < 3; p++) {
      g.globalAlpha = p === 0 ? 0.95 : 0.45
      g.lineWidth = p === 0 ? 6 : 2.8
      const jx = (hash(i, p) - 0.5) * 3.2, jy = (hash(p, i + 9) - 0.5) * 3.2
      g.strokeText(sc.letter, x0 + 42 + jx, 104 + jy)
    }
    // its number, beside the letter (not on it), two thirds of its height
    if (sc.number !== null) {
      g.globalAlpha = 0.95
      g.lineWidth = 5.5
      g.font = 'bold 66px Georgia, serif'
      g.strokeText(String(sc.number), x0 + 104, 118)
    }
    // a stray slip of the blade
    g.globalAlpha = 0.35
    g.lineWidth = 2
    g.beginPath()
    g.moveTo(x0 + 16 + hash(i, 3) * 20, 116)
    g.lineTo(x0 + 44 + hash(i, 4) * 28, 122)
    g.stroke()
    g.globalAlpha = 1
  }
}
